// Compatibility with scripts ALREADY generated by 0.9.0. Fixtures are immutable
// outputs of its original planner, not scripts synthesized by the current code.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync, existsSync, realpathSync } from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { fileURLToPath } from 'node:url';
import { montarArvore, resumirStream } from '../src/core/ledger.js';

const FIXTURES = fileURLToPath(new URL('./fixtures/legacy-0.9/', import.meta.url));
const CLI_URL = new URL('../src/cli.js', import.meta.url).href;
const provenance = JSON.parse(readFileSync(path.join(FIXTURES, 'provenance.json'), 'utf8'));
const hash = (bytes) => createHash('sha256').update(bytes).digest('hex');
// Original Bash scripts and these shebang fixtures require one POSIX process
// environment. Finding Git Bash/WSL from native Windows does not prove PATH,
// executable, or filesystem interoperability. Node executor tests cover Windows.
const bashAvailable = process.platform !== 'win32'
  && spawnSync('bash', ['--version'], { stdio: 'ignore' }).status === 0;

const SPEC = `# Spec: Valor legado

> feature: legacy
> status: em-implementacao

## Histórias

### US-001 — Calcular valor

Como cliente, quero calcular o valor, para conferir o resultado.

#### AC-001 — Valor calculado

- **Dado** um valor inicial
- **Quando** o cálculo executa
- **Então** o resultado é 42

## Suposições

Nenhuma.

## Perguntas em aberto

Nenhuma.
`;
const TASKS = `# Tasks: Valor legado

> feature: legacy

## T-001 — Implementar valor [pendente]

- Refs: AC-001
- Arquivos: src/value.js

## T-002 — Revisar documentação [pendente]

- Refs: AC-001
- Arquivos: docs/result.md
`;
const ACCEPTANCE = `import { test } from 'node:test';
import assert from 'node:assert/strict';
import { value } from '../src/value.js';
test('@spec:AC-001 valor calculado', () => assert.equal(value, 42));
`;

// Installed only in a temporary PATH: the legacy script cannot reach a real
// provider. It must use its original native flags and the previously pinned model.
const NATIVE_STUB = `#!/usr/bin/env node
const { writeFileSync, appendFileSync, mkdirSync } = require('node:fs');
const { spawnSync } = require('node:child_process');
const path = require('node:path');
const harness = path.basename(process.argv[1]);
const args = process.argv.slice(2);
const prompt = harness === 'codex' ? args[1] : args[args.indexOf('-p') + 1];
const id = prompt?.match(/Sua tarefa \\(somente ela\\):\\s*(T-\\d{3})/)?.[1];
if (!id || !['T-001', 'T-002'].includes(id)) throw new Error('Unexpected inference or discovery call');
if (harness === 'codex' ? args[0] !== 'exec' || !args.includes('--json') : !args.includes('stream-json')) throw new Error('Original native flags missing');
if (args[args.indexOf('--model') + 1] !== 'legacy-model') throw new Error('Pinned legacy model changed');
appendFileSync(process.env.ONP_LEGACY_CALLS, JSON.stringify({ id, harness, cwd: process.cwd(), args }) + '\\n');
const file = id === 'T-001' ? 'src/value.js' : 'docs/result.md';
mkdirSync(path.dirname(file), { recursive: true });
writeFileSync(file, id === 'T-001' ? 'export const value = 42;\\n' : '# Resultado\\n\\nValor: 42.\\n');
for (const argv of [['add', '--', file], ['commit', '-qm', id + ': legacy fixture']]) {
  const result = spawnSync('git', argv, { encoding: 'utf8' });
  if (result.status !== 0) throw new Error(result.stderr);
}
const emit = (event) => console.log(JSON.stringify(event));
if (harness === 'codex') {
  emit({ type: 'thread.started', thread_id: 'legacy-' + id });
  emit({ type: 'item.completed', item: { type: 'agent_message', text: 'implemented ' + id } });
  emit({ type: 'turn.completed', usage: { input_tokens: 5, output_tokens: 3 } });
} else {
  emit({ type: 'system', subtype: 'init', session_id: 'legacy-' + id, model: 'legacy-model' });
  emit({ type: 'result', subtype: 'success', is_error: false, result: 'implemented ' + id });
}
`;

test('fixtures 0.9 preservam os bytes originais e o formato de plano sem version', () => {
  assert.equal(provenance.version, '0.9.0');
  for (const [name, expected] of Object.entries(provenance.sha256)) {
    assert.equal(hash(readFileSync(path.join(FIXTURES, name))), expected, name);
    if (name.endsWith('.json')) {
      const plan = JSON.parse(readFileSync(path.join(FIXTURES, name), 'utf8'));
      assert.equal(plan.version, undefined);
      assert.equal(plan.engine, undefined);
      assert.equal(plan.config, undefined);
    }
  }
});

for (const harness of ['claude', 'codex', 'cursor']) {
  test(`0.9 ${harness}: shell original executa com motor atualizado e preserva artefatos antigos`, {
    skip: !bashAvailable && 'Historical 0.9 Bash fixtures require POSIX; the new Node executor has separate Windows tests.',
    timeout: 30000,
  }, async (t) => {
    const tmp = realpathSync(mkdtempSync(path.join(os.tmpdir(), `onp-legacy-${harness}-`)));
    t.after(() => rmSync(tmp, { recursive: true, force: true }));
    const repo = path.join(tmp, 'legacy-project');
    const home = path.join(tmp, 'home');
    const nativeDir = path.join(tmp, 'native');
    const base = path.join(repo, '.spec/features/legacy');
    const callsFile = path.join(tmp, 'calls.jsonl');
    for (const dir of [base, nativeDir, path.join(repo, 'test'), path.join(home, 'painel')]) mkdirSync(dir, { recursive: true });
    for (const binary of ['claude', 'codex', 'agent', 'cursor-agent']) writeFileSync(path.join(nativeDir, binary), NATIVE_STUB, { mode: 0o755 });
    const env = { ...process.env, PATH: `${nativeDir}${path.delimiter}${path.dirname(process.execPath)}${path.delimiter}${process.env.PATH}`, ONP_SPEC_HOME: home, ONP_LEGACY_CALLS: callsFile };
    delete env.NODE_TEST_CONTEXT;
    const git = (args) => spawnSync('git', args, { cwd: repo, env, encoding: 'utf8' });
    const cli = (args) => spawnSync(process.execPath, ['engine.mjs', ...args], { cwd: repo, env, encoding: 'utf8', timeout: 15000 });
    const run = (args = []) => spawnSync('bash', ['.spec/features/legacy/executar-tarefas.sh', ...args], { cwd: repo, env, encoding: 'utf8', timeout: 15000 });
    const events = () => readFileSync(path.join(home, 'painel/ledger.jsonl'), 'utf8').trim().split('\n').map(JSON.parse);
    const calls = () => existsSync(callsFile) ? readFileSync(callsFile, 'utf8').trim().split('\n').map(JSON.parse) : [];

    // enginePath was set when generating the original fixture, exactly as a
    // 0.9 installation would pin its embedded engine. Only that engine updates.
    writeFileSync(path.join(repo, 'engine.mjs'), `import { run } from ${JSON.stringify(CLI_URL)}; process.exitCode = await run(process.argv.slice(2));\n`);
    writeFileSync(path.join(repo, 'package.json'), '{"type":"module"}\n');
    writeFileSync(path.join(repo, 'onpspec.config.json'), JSON.stringify({ testCommand: 'node --test --test-reporter=tap test/acceptance.test.js', reporter: 'tap', paralelo: { model: 'legacy-model', resumoModel: 'legacy-summary-model' } }));
    writeFileSync(path.join(repo, '.spec/constituicao.md'), '# Constituição\n\n## P-001 [DEVE] Requisitos têm prova\n\n- verificação(gate): intrínseca ao audit\n');
    writeFileSync(path.join(repo, 'test/acceptance.test.js'), ACCEPTANCE);
    writeFileSync(path.join(base, 'spec.md'), SPEC);
    writeFileSync(path.join(base, 'tasks.md'), TASKS);
    writeFileSync(path.join(base, 'plano.json'), readFileSync(path.join(FIXTURES, `${harness}.json`)));
    writeFileSync(path.join(base, 'executar-tarefas.sh'), readFileSync(path.join(FIXTURES, `${harness}.sh`)));
    writeFileSync(path.join(base, 'plano-execucao.md'), '# Meu plano antigo\n\nAnotações que devem permanecer.\n');
    writeFileSync(path.join(base, 'plano-execucao.html'), '<p>Artefato histórico: conteúdo preservado.</p>\n');
    const preserved = ['spec.md', 'plano.json', 'executar-tarefas.sh', 'plano-execucao.md', 'plano-execucao.html'];
    const before = Object.fromEntries(preserved.map((name) => [name, hash(readFileSync(path.join(base, name)))]));
    const plan = JSON.parse(readFileSync(path.join(base, 'plano.json'), 'utf8'));
    writeFileSync(path.join(home, 'painel/ledger.jsonl'), JSON.stringify({ ts: new Date().toISOString(), tipo: 'plano', runId: plan.runId, projeto: 'legacy-project', projetoDir: repo, feature: 'legacy', agent: harness, plano: plan }) + '\n');
    for (const args of [['init', '-q'], ['config', 'user.email', 'test@example.invalid'], ['config', 'user.name', 'Legacy fixture'], ['add', '-A'], ['commit', '-qm', 'existing 0.9 project']]) assert.equal(git(args).status, 0);

    await t.test('lista sem inferência e executa faixa + tarefa sequencial com gate real', () => {
      const listing = run(['--listar']);
      assert.equal(listing.status, 0, listing.stdout + listing.stderr);
      assert.match(listing.stdout, /faixa-1.*T-001/);
      assert.match(listing.stdout, /T-002/);
      assert.equal(calls().length, 0);
      const result = run();
      assert.equal(result.status, 0, result.stdout + result.stderr);
      assert.deepEqual(calls().map(({ id }) => id), ['T-001', 'T-002']);
      assert.match(calls()[0].cwd, /legacy-project-legacy-faixa-1$/);
      assert.equal(realpathSync(calls()[1].cwd), realpathSync(repo));
      assert.match(readFileSync(path.join(base, 'tasks.md'), 'utf8'), /T-001 — Implementar valor \[concluida\]/);
      assert.match(readFileSync(path.join(base, 'tasks.md'), 'utf8'), /T-002 — Revisar documentação \[concluida\]/);
      const verification = JSON.parse(readFileSync(path.join(repo, '.spec/verification/legacy.json'), 'utf8'));
      assert.equal(verification.results['AC-001'].status, 'pass');
      assert.equal(verification.testsParsed, 1);
      const state = montarArvore(events())[0].execucoes[0];
      assert.equal(state.faixas[0].estado, 'mesclada');
      assert.equal(state.concluidas, 2);
      assert.deepEqual(state.gate, { verify: 0, audit: 0 });
      assert.equal(state.fim, 0);
    });

    await t.test('preserva APIs evento, stream-resumo e resumo para o ledger 0.9', () => {
      for (const key of ['faixa-1--T-001', 'seq--T-002']) {
        const result = cli(['stream-resumo', plan.runId, key]);
        assert.equal(result.status, 0, result.stderr);
        const stream = readFileSync(path.join(home, 'painel/streams', plan.runId, `${key}.jsonl`), 'utf8');
        assert.equal(resumirStream(stream).resumo.status, 'sucesso');
      }
      const context = cli(['resumo', '--run', plan.runId, '--contexto']);
      assert.equal(context.status, 0, context.stderr);
      assert.match(context.stdout, /legacy.*2 de 2 tarefa/);
      assert.equal(cli(['resumo', '--run', plan.runId, '--gravar']).status, 0);
      assert.ok(events().some((event) => event.tipo === 'resumo' && event.origem === 'motor'));
    });

    await t.test('gate continua detectando regressão sem repetir inferência', () => {
      writeFileSync(path.join(repo, 'test/acceptance.test.js'), ACCEPTANCE.replace('value, 42', 'value, 41'));
      assert.equal(git(['add', 'test/acceptance.test.js']).status, 0);
      assert.equal(git(['commit', '-qm', 'acceptance regression fixture']).status, 0);
      const result = run(['--gate']);
      assert.equal(result.status, 1, result.stdout + result.stderr);
      assert.equal(calls().length, 2);
      const state = montarArvore(events())[0].execucoes[0];
      assert.deepEqual(state.gate, { verify: 1, audit: 1 });
      assert.equal(state.fim, 1);
    });

    for (const name of preserved) assert.equal(hash(readFileSync(path.join(base, name))), before[name], `${name} must stay byte-for-byte unchanged`);
    assert.ok(!existsSync(path.join(base, 'executar-tarefas.mjs')), 'Running old artifacts does not migrate them implicitly');
  });
}
